  "34017": { // LA-level due diligence (Batch 4)
    notes: "New Jersey municipal tax-lien county. Hudson cities (Jersey City, Hoboken, Bayonne, Union City, North Bergen, etc.) each run annual (or accelerated) tax sales for unpaid taxes and municipal charges — typically online via RealAuction *.newjerseytaxsale.com. No county-level tax deed auction. Certificate purchasers hold a lien with statutory interest/premium; foreclosure of certificate is a separate judicial/In Rem process. Sheriff mortgage sales are a different channel.",
    auctionFormat: "Varies by municipality (online tax lien auctions common)",
    auctionPlatform: { label: "Municipal RealAuction NJ tax sales", url: "https://www.realauction.com/" },
    auctionFrequency: "At least one tax sale per municipality per year (dates vary by city)",
    depositRules: "Register on the specific municipality’s tax-sale site; deposit and ACH rules in that sale’s bidder terms. Lien purchase funds via platform; not a deed closing.",
    taxCollector: { label: "Municipal tax collectors in Hudson County", url: "https://www.hudsoncountynj.org/" },
    clerkOfCourt: { label: "Hudson County Register / Clerk", url: "https://www.hudsoncountynj.org/" },
    propertyAppraiser: { label: "Municipal assessors (Jersey City, Hoboken, etc.)", url: "https://www.jerseycitynj.gov/" },
    survivingLiens: "Tax sale certificate is superior municipal lien but does not wipe private mortgages until certificate is foreclosed. Federal and other liens need independent review.",
    quietTitle: "After certificate foreclosure, quiet title often used for marketable title in high-value Hudson markets.",
    gisMap: { label: "Jersey City / Hudson municipal GIS portals", url: "https://www.jerseycitynj.gov/" },
    growthNeighborhoods: [
      { name: "Downtown Jersey City / Exchange Place", why: "PATH-adjacent employment and multifamily demand with strong pricing" },
      { name: "Hoboken waterfront / uptown edge", why: "Extremely tight inventory and high renter/owner demand" },
      { name: "Journal Square / Bergen-Lafayette selective nodes", why: "Relative value and redevelopment pipeline vs. waterfront cores" },
    ],
    asOf: "2026-07",
    sources: [
      "https://www.tctanj.org/cn/webpage.cfm?tpid=14659",
      "https://www.realauction.com/",
      "https://www.hudsoncountynj.org/",
    ],
  },
